    /// 解码后的脚本文本（static let 天然惰性，只解码一次）
    static let lib: String = decode(libBase64)
    static let core: String = decode(coreBase64)

    private static func decode(_ b64: String) -> String {
        guard let data = Data(base64Encoded: b64, options: .ignoreUnknownCharacters) else { return "" }
        return String(decoding: data, as: UTF8.self)
    }
